-- Rollback manual da bot_v2_port_texts. IMPORTANTE ao voltar para a imagem antiga: o código da v1
-- lê bot_texts sem filtro por chave (findMany) e o Prisma antigo NÃO conhece as chaves v2 — linhas
-- com elas quebram a tela de mensagens e a API de textos para essas empresas. Apague-as.
-- (Edições feitas depois do porte nessas chaves se perdem; as linhas legadas MAIN_MENU e
-- APPOINTMENT_ACTIONS nunca foram apagadas.)
DELETE FROM "bot_texts" WHERE "key"::text IN ('MENU_PROMPT', 'MENU_HINT', 'FOOTER_HINT', 'CONTINUE_PROMPT', 'HELP', 'NO_SERVICES', 'NEXT_AVAILABLE', 'DATE_OUT_OF_RANGE', 'TIME_NOT_AVAILABLE', 'ITEM_UNAVAILABLE', 'APPOINTMENT_LIMIT', 'NAME_INVALID', 'NAME_TOO_LONG', 'CONFIRM_RESCHEDULE', 'CONFIRM_EDIT', 'POST_ACTION_MENU', 'APPOINTMENT_DETAIL', 'APPOINTMENT_LOCKED', 'CANCEL_KEPT', 'HUMAN_HANDOFF_OFF_HOURS', 'BOT_RESUMED', 'INVALID_BACK_TO_MENU', 'AMBIGUOUS_OPTION', 'RESUME_OFFER', 'THANKS_REPLY', 'TECH_ERROR', 'LABEL_MENU_BOOK', 'LABEL_MENU_MY', 'LABEL_MENU_HUMAN', 'LABEL_ANY_PROFESSIONAL', 'LABEL_NEXT_AVAILABLE', 'LABEL_BY_DAY', 'LABEL_EDIT', 'LABEL_EDIT_SERVICE', 'LABEL_EDIT_PROFESSIONAL', 'LABEL_EDIT_DATETIME', 'LABEL_EDIT_NAME', 'LABEL_RESCHEDULE', 'LABEL_CANCEL_APPOINTMENT', 'LABEL_BOOK_ANOTHER', 'LABEL_FINISH', 'LABEL_CONTINUE', 'LABEL_START_OVER', 'LABEL_BACK', 'LABEL_OTHER_SERVICE', 'LABEL_PREVIOUS');
